AWS API Gateway / ALB.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the AWS API Gateway / ALB container

Container_Boundary(aws_api_gateway_alb, "AWS API Gateway / ALB") {
    Component(PaymentIngressALB, "Payment Ingress ALB", "AWS ALB", "Handles high-throughput payment ingestion for sub-50ms latency.")
    Component(ManagementAPIGateway, "Management API Gateway", "AWS API Gateway", "Manages case management APIs and IdP integrations.")
}

Rel(PaymentIngressALB, RealTimeScoringEngine, "Forwards scoring requests using local circuit breaker", "mTLS")
Rel(ManagementAPIGateway, CaseManagementBackend, "Routes administrative and review APIs", "HTTPS")

@enduml

Redis Cache.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Redis Cache container

Container_Boundary(redis_cache, "Redis Cache") {
    Component(In_Memory_Data_Store, "In-Memory Data Store", "Redis Engine (Redis 7.x, Graviton2 cache.m6g.large)", "Performs sub-millisecond feature lookups using RESP over TCP with mTLS and TLS 1.3, enforcing least-privilege access via native ACLs.")
    Component(Persistence_Backup_Worker, "Persistence/Backup Worker", "AWS ElastiCache Managed Snapshot & AWS KMS", "Handles daily automated backups with a 7-day retention period and at-rest encryption for cached cryptographic tokens and feature sets.")
}

Rel(In_Memory_Data_Store, Persistence_Backup_Worker, "Stores daily automated backups with a 7-day retention period to Amazon S3", "AWS ElastiCache Managed Snapshot")

@startuml

Messaging Bus.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(messaging_bus, "Messaging Bus") {
    Component(SQS_Standard_Queue, "SQS Standard Queue", "Amazon SQS Standard", "Handles high-throughput, at-least-once delivery of scoring decisions and telemetry events.")
    Component(SQS_FIFO_Queue, "SQS FIFO Queue", "Amazon SQS FIFO", "Ensures guaranteed ordering for audit and analyst override events.")
    Component(Dead_Letter_Queues, "Dead-Letter Queues", "Amazon SQS DLQ", "Captures and isolates failed message processing attempts for error analysis.")
}

Rel(SQS_Standard_Queue, SQS_FIFO_Queue, "Routes ordered processing events")
Rel(SQS_FIFO_Queue, Dead_Letter_Queues, "Forwards unprocessable messages")
@enduml
